package postgres

import (
	"context"
	"database/sql"
	"fmt"
	"strings"

	"github.com/kosmassp/SimpleOrm/go/orm/internal/core"
	"github.com/kosmassp/SimpleOrm/go/orm/internal/render"
)

// Dialect is the PostgreSQL implementation of core.Dialect (§7.25, ADR-0025),
// backed by pgx. Every rendered string follows spec/dialects.md: always
// double-quoted identifiers, `generated by default as identity` keys,
// `returning` write-back, storage types spelled the way format_type reports
// them. It also implements core.StatementDescriber (SchemaGuard) and
// core.TemporalMarkers (the VAL-020 read rule by column type).
type Dialect struct {
	cachedPlan CachedPlanPolicy
}

// CachedPlanPolicy says what a connection does when PostgreSQL refuses a statement pgx prepared and
// cached earlier because the table changed under it — SQLSTATE 0A000 "cached plan must not change
// result type" (ADR-0040 add.1, spec/dialects.md Clarifications). pgx itself only invalidates the
// cached statement on any error; it never retries.
type CachedPlanPolicy int

const (
	// CachedPlanRetryOnce (the default) re-runs the statement once — pgx re-prepares it — when no
	// transaction is active on the connection: the failed statement ran in its own implicit
	// transaction, so nothing of it happened. Inside a transaction PostgreSQL has already aborted
	// the transaction, so the error surfaces as TX-002 and the caller rolls back and reruns it.
	CachedPlanRetryOnce CachedPlanPolicy = iota
	// CachedPlanSurface surfaces TX-002, in or out of a transaction.
	CachedPlanSurface
)

// Option configures the dialect at construction.
type Option func(*Dialect)

// WithCachedPlanPolicy chooses the cached-plan behaviour (default CachedPlanRetryOnce).
func WithCachedPlanPolicy(policy CachedPlanPolicy) Option {
	return func(d *Dialect) { d.cachedPlan = policy }
}

// New is the dialect. Its only setting is a driver matter, not a seam member: the cached-plan
// policy of the connections it opens.
func New(options ...Option) *Dialect {
	d := &Dialect{}
	for _, option := range options {
		option(d)
	}
	return d
}

// Name is the CLI name of the dialect (ADR-0043): stamped into every snapshot written for it.
func (*Dialect) Name() string { return "postgres" }

var (
	_ core.Dialect            = (*Dialect)(nil)
	_ core.StatementDescriber = (*Dialect)(nil)
	_ core.TemporalMarkers    = (*Dialect)(nil)
)

// CreateConnection opens the pool for a native pgx connection string (a
// `postgres://user:password@host:port/database` URL or a key/value DSN). The pool
// rewrites `@name` placeholders to the `$n` positions pgx requires (see the
// package comment); nothing connects until first use.
func (d *Dialect) CreateConnection(connectionString string) (*sql.DB, error) {
	return openPool(connectionString, d.cachedPlan)
}

// QuoteIdentifier always double-quotes, doubling any embedded `"`: lowercase
// snake_case names match the catalog fold, so quoting is reserved-word-proof
// and changes nothing else (ADR-0025).
func (*Dialect) QuoteIdentifier(identifier string) string {
	return `"` + strings.ReplaceAll(identifier, `"`, `""`) + `"`
}

// LimitOffsetClause is the plain `limit`/`offset` form; offset alone needs no
// `limit all` on PostgreSQL.
func (*Dialect) LimitOffsetClause(limitParameter, offsetParameter string) string {
	switch {
	case limitParameter != "" && offsetParameter != "":
		return "limit " + limitParameter + " offset " + offsetParameter
	case limitParameter != "":
		return "limit " + limitParameter
	case offsetParameter != "":
		return "offset " + offsetParameter
	}
	return ""
}

func (d *Dialect) SelectSQL(ast *core.SelectAst, bind core.BindCriteriaParameter) (string, error) {
	return render.SelectSQL(d, ast, bind)
}

func (*Dialect) PagingRequiresOrderBy() bool { return false }

// SupportsRowValueIn is true: `(a, b) in (select …)` parses natively.
func (*Dialect) SupportsRowValueIn() bool { return true }

// SupportsArrayParameters is true: a collection binds as one typed slice, which pgx encodes as the array (`= any(@ids)`).
func (*Dialect) SupportsArrayParameters() bool { return true }

// BindsTemporalsNatively is true: `timestamptz >= text` refuses, so temporals bind as UTC time.Time values.
func (*Dialect) BindsTemporalsNatively() bool { return true }

func (*Dialect) SupportsMaterializedViews() bool { return true }

// SupportsProcedures is declared and dormant (no execution machinery before Level 4).
func (*Dialect) SupportsProcedures() bool { return true }

func (*Dialect) SupportsTransactionalDDL() bool { return true }

// IsMarkerlessTemporal: only `timestamp without time zone` stores instants with no marker
// (core.TemporalMarkers); pgx names it TIMESTAMP, timestamptz TIMESTAMPTZ.
func (*Dialect) IsMarkerlessTemporal(databaseTypeName string) bool {
	switch strings.ToUpper(strings.TrimSpace(databaseTypeName)) {
	case "TIMESTAMP", "TIMESTAMP WITHOUT TIME ZONE":
		return true
	}
	return false
}

// --- introspection (§7.25): pg_catalog, flags as bigint ---
//
// The result columns carry the spec's names on every non-SQLite dialect of every
// implementation (spec/dialects.md "Introspection result shapes"), so a consumer
// may read by name or, as this port and the reference do, by ordinal. `pk` is a
// presence flag here, not an ordinal.

func (*Dialect) ColumnsInfoSQL() string {
	return "select a.attname as name,\n" +
		"       format_type(a.atttypid, a.atttypmod) as type,\n" +
		"       (case when a.attnotnull then 1 else 0 end)::bigint as \"notnull\",\n" +
		"       (case when exists (\n" +
		"           select 1 from pg_index i\n" +
		"           where i.indrelid = a.attrelid and i.indisprimary and a.attnum = any(i.indkey)\n" +
		"       ) then 1 else 0 end)::bigint as pk,\n" +
		"       (case when a.attidentity in ('a', 'd') then 1 else 0 end)::bigint as generated\n" +
		"from pg_attribute a\n" +
		"where a.attrelid = to_regclass(@relation) and a.attnum > 0 and not a.attisdropped\n" +
		"order by a.attnum"
}

func (*Dialect) ViewDefinitionSQL() string {
	return "select pg_get_viewdef(c.oid, true) as definition from pg_class c\n" +
		"where c.oid = to_regclass(@relation) and c.relkind in ('v', 'm')"
}

func (*Dialect) IndexesInfoSQL() string {
	return "select ic.relname as index_name,\n" +
		"       (case when i.indisunique then 1 else 0 end)::bigint as \"unique\",\n" +
		"       k.n::bigint as seqno,\n" +
		"       a.attname as \"column\",\n" +
		"       (case when (i.indoption[k.n] & 1) <> 0 then 1 else 0 end)::bigint as \"desc\"\n" +
		"from pg_index i\n" +
		"join pg_class ic on ic.oid = i.indexrelid\n" +
		"cross join lateral generate_series(0, i.indnkeyatts - 1) as k(n)\n" +
		"join pg_attribute a on a.attrelid = i.indrelid and a.attnum = i.indkey[k.n]\n" +
		"where i.indrelid = to_regclass(@relation)\n" +
		"  and not i.indisprimary\n" +
		"  and not exists (select 1 from pg_constraint con where con.conindid = i.indexrelid)\n" +
		"order by ic.relname, k.n"
}

// IsDeclaredTypeCompatible is the declared-type → token table (§7.19, spec/dialects.md). The declared
// type is reduced to its base name first, so `character varying(100)` and
// `timestamp(3) with time zone` read as their bare types; an empty name
// (PostgreSQL always declares one) is compatible with nothing. Both timestamp
// types are type-compatible with datetime: the marker rule applies per value
// at read time (IsMarkerlessTemporal).
func (*Dialect) IsDeclaredTypeCompatible(declaredType string, columnType core.ColumnType) bool {
	switch baseTypeName(declaredType) {
	case "integer", "int4":
		return columnType == core.TypeInt32 || columnType == core.TypeInt64 || columnType == core.TypeInt16 ||
			columnType == core.TypeEnumInt
	case "bigint", "int8":
		return columnType == core.TypeInt64 || columnType == core.TypeEnumInt
	case "smallint", "int2":
		return columnType == core.TypeInt16 || columnType == core.TypeInt32 || columnType == core.TypeInt64 ||
			columnType == core.TypeEnumInt
	case "boolean", "bool":
		return columnType == core.TypeBool
	case "numeric", "decimal", "money":
		return columnType == core.TypeDecimal
	case "double precision", "float8":
		return columnType == core.TypeDouble
	case "real", "float4":
		return columnType == core.TypeFloat
	case "text", "character varying", "varchar", "character", "char":
		return columnType == core.TypeString || columnType == core.TypeEnumText
	case "name":
		return columnType == core.TypeString
	case "bytea":
		return columnType == core.TypeBytes
	case "uuid":
		return columnType == core.TypeGUID
	case "timestamp with time zone", "timestamptz":
		return columnType == core.TypeDateTime || columnType == core.TypeDateTimeOffset
	case "timestamp without time zone", "timestamp":
		return columnType == core.TypeDateTime
	case "date":
		return columnType == core.TypeDateTime || columnType == core.TypeDate
	case "time without time zone", "time":
		return columnType == core.TypeTime
	}
	return false
}

// baseTypeName reduces a declared type to its base name: trimmed, lowercased, every
// parenthesized length or precision removed (mid-name too: `timestamp(3) with time
// zone` → `timestamp with time zone`), whitespace collapsed.
func baseTypeName(declaredType string) string {
	var b strings.Builder
	depth := 0
	for _, r := range strings.ToLower(strings.TrimSpace(declaredType)) {
		switch {
		case r == '(':
			depth++
		case r == ')':
			if depth > 0 {
				depth--
			}
		case depth == 0:
			b.WriteRune(r)
		}
	}
	return strings.Join(strings.Fields(b.String()), " ")
}

// StorageType is the token → PostgreSQL type per spec/dialects.md, spelled the way format_type
// reports it so introspected and rendered types compare cleanly. Strings, JSON, enum names, and
// handler types are `text` — keys included, no length hack needed.
func (*Dialect) StorageType(_ *core.EntityMap, property *core.PropertyMap) string {
	switch property.ColumnType {
	case core.TypeInt16:
		return "smallint"
	case core.TypeInt32, core.TypeEnumInt:
		return "integer"
	case core.TypeInt64:
		return "bigint"
	case core.TypeBool:
		return "boolean"
	case core.TypeDecimal:
		if property.Precision > 0 {
			return fmt.Sprintf("numeric(%d,%d)", property.Precision, property.Scale)
		}
		return "numeric"
	case core.TypeDouble:
		return "double precision"
	case core.TypeFloat:
		return "real"
	case core.TypeGUID:
		return "uuid"
	case core.TypeBytes:
		return "bytea"
	case core.TypeDateTime, core.TypeDateTimeOffset:
		return "timestamp with time zone"
	case core.TypeDate:
		return "date"
	case core.TypeTime:
		return "time without time zone"
	}
	// string, JSON, enum names, and handler types: a Length facet is a character varying(n) (a key needs no length hack).
	if property.ColumnType == core.TypeString && property.Length > 0 {
		return fmt.Sprintf("character varying(%d)", property.Length)
	}
	return "text"
}

// --- migrations (§7.23) ---

// BeginMigrationRunLock begins the run's transaction and takes the advisory lock inside it:
// `pg_advisory_xact_lock` is transaction-scoped, so it can never leak past a rollback, and
// DDL is transactional, so a failed run applies nothing. The key pair is arbitrary but fixed
// (ASCII `Simp`, `leOr`); a 60 s lock_timeout turns a held lock into the database's own error
// instead of an indefinite wait — the run has not started.
func (*Dialect) BeginMigrationRunLock(ctx context.Context, conn *sql.Conn) (*sql.Tx, error) {
	tx, err := conn.BeginTx(ctx, nil)
	if err != nil {
		return nil, err
	}
	for _, statement := range []string{
		"set local lock_timeout = '60s'",
		"select pg_advisory_xact_lock(1399418224, 1818578802)",
	} {
		if _, err := tx.ExecContext(ctx, statement); err != nil {
			_ = tx.Rollback() // the lock was never taken; the acquisition error is the one to report
			return nil, err
		}
	}
	return tx, nil
}

func (*Dialect) VersionTableSQL() string {
	return "create table if not exists schema_version (\n" +
		"    version      bigint not null,\n" +
		"    object       text not null,\n" +
		"    description  text not null,\n" +
		"    checksum     text not null,\n" +
		"    applied_at   text not null,\n" +
		"    execution_ms bigint not null,\n" +
		"    primary key (version, object)\n" +
		")"
}

func (d *Dialect) RenameTableSQL(fromName, toName string) string {
	return "alter table " + d.QuoteIdentifier(fromName) + " rename to " + d.QuoteIdentifier(toName)
}

func (d *Dialect) RenameColumnSQL(table, fromName, toName string) string {
	return "alter table " + d.QuoteIdentifier(table) + " rename column " + d.QuoteIdentifier(fromName) +
		" to " + d.QuoteIdentifier(toName)
}

func (d *Dialect) AddColumnSQL(table, column, storageType string, nullable bool, defaultSQL string) string {
	sql := "alter table " + d.QuoteIdentifier(table) + " add column " + d.QuoteIdentifier(column) + " " + storageType
	if !nullable {
		sql += " not null"
	}
	if defaultSQL != "" {
		sql += " default " + defaultSQL
	}
	return sql
}

func (d *Dialect) DropColumnSQL(table, column string) string {
	return "alter table " + d.QuoteIdentifier(table) + " drop column " + d.QuoteIdentifier(column)
}

func (d *Dialect) DropTableSQL(table string) string { return "drop table " + d.QuoteIdentifier(table) }

// DropIndexSQL needs no table: PostgreSQL index names are schema-scoped.
func (d *Dialect) DropIndexSQL(table, index string) string {
	return "drop index " + d.QuoteIdentifier(index)
}

// --- generated DDL and CRUD from the EntityMap (ADR-0011, ADR-0008 add.3) ---

// CreateViewSQL is `create or replace view` for a view and `create materialized view if not exists`
// for a materialized view (a materialized view has no replace).
func (d *Dialect) CreateViewSQL(m *core.EntityMap) string {
	return d.CreateViewFromBodySQL(m.RelationName, m.DefiningSQL, m.Kind == core.RelationMaterializedView)
}

func (d *Dialect) CreateTableSQL(m *core.EntityMap) string {
	var b strings.Builder
	b.WriteString("create table if not exists ")
	b.WriteString(d.QuoteIdentifier(m.RelationName))
	b.WriteString(" (")
	first := true
	for _, property := range m.Properties {
		if first {
			b.WriteString("\n    ")
		} else {
			b.WriteString(",\n    ")
		}
		first = false
		b.WriteString(d.QuoteIdentifier(property.ColumnName))
		b.WriteByte(' ')
		b.WriteString(d.StorageType(m, property))
		if m.KeyStrategy == core.KeyDatabaseGenerated && property.IsKey {
			// "By default" so fixtures may insert explicit keys.
			b.WriteString(" generated by default as identity primary key")
			continue
		}
		if !property.IsNullable {
			b.WriteString(" not null")
		}
		if m.KeyStrategy == core.KeyClientGuid && property.IsKey {
			b.WriteString(" primary key")
		}
	}
	if m.KeyStrategy == core.KeyNatural && len(m.KeyProperties) > 0 {
		b.WriteString(",\n    primary key (")
		b.WriteString(strings.Join(d.columnNames(m.KeyProperties), ", "))
		b.WriteByte(')')
	}
	b.WriteString("\n)")
	return b.String()
}

func (d *Dialect) CreateIndexSQL(m *core.EntityMap) []string {
	statements := make([]string, 0, len(m.Indexes))
	for _, index := range m.Indexes {
		unique := ""
		if index.Unique {
			unique = "unique "
		}
		columns := make([]string, len(index.Columns))
		for i, column := range index.Columns {
			columns[i] = d.QuoteIdentifier(column.ColumnName)
			if column.Descending {
				columns[i] += " desc"
			}
		}
		statements = append(statements,
			"create "+unique+"index if not exists "+d.QuoteIdentifier(index.Name)+" on "+
				d.QuoteIdentifier(m.RelationName)+" ("+strings.Join(columns, ", ")+")")
	}
	return statements
}

func (d *Dialect) InsertSQL(m *core.EntityMap) string {
	var columns, placeholders []string
	for _, p := range m.Properties {
		if p.IsGenerated {
			continue
		}
		columns = append(columns, d.QuoteIdentifier(p.ColumnName))
		placeholders = append(placeholders, "@"+p.ColumnName)
	}
	sql := "insert into " + d.QuoteIdentifier(m.RelationName) +
		" (" + strings.Join(columns, ", ") + ")" +
		" values (" + strings.Join(placeholders, ", ") + ")"
	if m.KeyStrategy == core.KeyDatabaseGenerated {
		sql += " returning " + d.QuoteIdentifier(m.KeyProperties[0].ColumnName)
	}
	return sql
}

func (d *Dialect) UpdateSQL(m *core.EntityMap) string {
	// Generated non-key columns are database-owned: never in SET (mirrors the
	// insert exclusion and Update's binding filter).
	var set []*core.PropertyMap
	for _, p := range m.Properties {
		if !p.IsKey && !p.IsVersion && !p.IsGenerated {
			set = append(set, p)
		}
	}
	return d.renderUpdate(m, set)
}

func (d *Dialect) UpdateOnlySQL(m *core.EntityMap, properties []*core.PropertyMap) string {
	return d.renderUpdate(m, properties)
}

func (d *Dialect) renderUpdate(m *core.EntityMap, set []*core.PropertyMap) string {
	var assignments []string
	for _, p := range set {
		assignments = append(assignments, d.QuoteIdentifier(p.ColumnName)+" = @"+p.ColumnName)
	}
	sql := "update " + d.QuoteIdentifier(m.RelationName)
	if version := m.VersionProperty; version != nil {
		column := d.QuoteIdentifier(version.ColumnName)
		assignments = append(assignments, column+" = "+column+" + 1")
	}
	sql += " set " + strings.Join(assignments, ", ") + " where " + d.keyPredicate(m)
	if version := m.VersionProperty; version != nil {
		sql += " and " + d.QuoteIdentifier(version.ColumnName) + " = @" + version.ColumnName
	}
	return sql
}

func (d *Dialect) DeleteSQL(m *core.EntityMap, checkVersion bool) string {
	sql := "delete from " + d.QuoteIdentifier(m.RelationName) + " where " + d.keyPredicate(m)
	if version := m.VersionProperty; checkVersion && version != nil {
		sql += " and " + d.QuoteIdentifier(version.ColumnName) + " = @" + version.ColumnName
	}
	return sql
}

// ReportsAffectedRowsBySelect is false: the driver's count is the statement's own, triggers or not
// (spec/dialects.md "Update and delete — the affected-row count").
func (*Dialect) ReportsAffectedRowsBySelect() bool { return false }

// SupportsStatementBatching is true: a planned message goes out as one pgx Batch pipeline on the session's
// connection (SendMessage, batch.go; ADR-0044, spec/dialects.md "Statement batching").
func (*Dialect) SupportsStatementBatching() bool { return true }

// MaxParametersPerMessage is 0, no cap: the plan is cut by statement count alone on PostgreSQL.
func (*Dialect) MaxParametersPerMessage() int { return 0 }

func (d *Dialect) keyPredicate(m *core.EntityMap) string {
	parts := make([]string, len(m.KeyProperties))
	for i, key := range m.KeyProperties {
		parts[i] = d.QuoteIdentifier(key.ColumnName) + " = @" + key.ColumnName
	}
	return strings.Join(parts, " and ")
}

func (d *Dialect) columnNames(properties []*core.PropertyMap) []string {
	names := make([]string, len(properties))
	for i, p := range properties {
		names[i] = d.QuoteIdentifier(p.ColumnName)
	}
	return names
}

// describeColumnsSQL resolves the described result columns' type names (format_type), base tables
// (regclass, search-path-aware so `to_regclass` resolves it back), and origin column names, in one
// round trip over the three parallel arrays of the statement description.
const describeColumnsSQL = "select i.ord::bigint, format_type(i.type_oid::oid, -1), " +
	"coalesce(c.oid::regclass::text, ''), coalesce(a.attname::text, '')\n" +
	"from unnest($1::bigint[], $2::bigint[], $3::bigint[]) with ordinality as i(type_oid, table_oid, attnum, ord)\n" +
	"left join pg_class c on c.oid = nullif(i.table_oid, 0)::oid\n" +
	"left join pg_attribute a on a.attrelid = c.oid and a.attnum = i.attnum\n" +
	"order by i.ord"

// DescribeStatement parses and describes the statement on the server without
// executing it (core.StatementDescriber): the rewritten statement is prepared
// as the unnamed server-side statement (parse + describe), whose field
// descriptions carry each result column's type OID and base table/column
// numbers; one catalog query turns those into names. A statement the server
// cannot parse — or whose parameter types it cannot infer from context — is
// returned as the database's error (SchemaGuard reports it as VAL-001).
func (*Dialect) DescribeStatement(ctx context.Context, connection *sql.Conn, statement string) ([]core.ColumnDescription, error) {
	var described []core.ColumnDescription
	err := connection.Raw(func(driverConn any) error {
		c, ok := driverConn.(*conn)
		if !ok {
			return fmt.Errorf("the %T driver connection is not a SimpleOrm postgres connection", driverConn)
		}
		pgxConn := c.inner.Conn()

		// An error inside a transaction aborts it on PostgreSQL, and SchemaGuard describes inside its
		// shield transaction: a savepoint keeps one unparseable statement from failing every later one.
		inTransaction := pgxConn.PgConn().TxStatus() == 'T'
		if inTransaction {
			if _, err := pgxConn.Exec(ctx, "savepoint simpleorm_describe"); err != nil {
				return err
			}
		}
		description, err := pgxConn.PgConn().Prepare(ctx, "", rewritePlaceholders(statement).sql, nil)
		if inTransaction {
			rollback := "release savepoint simpleorm_describe"
			if err != nil {
				rollback = "rollback to savepoint simpleorm_describe"
			}
			if _, releaseErr := pgxConn.Exec(ctx, rollback); releaseErr != nil && err == nil {
				return releaseErr
			}
		}
		if err != nil {
			return err
		}
		fields := description.Fields
		described = make([]core.ColumnDescription, len(fields))
		if len(fields) == 0 {
			return nil
		}

		typeOIDs := make([]int64, len(fields))
		tableOIDs := make([]int64, len(fields))
		attributeNumbers := make([]int64, len(fields))
		for i, field := range fields {
			described[i].Name = field.Name
			typeOIDs[i] = int64(field.DataTypeOID)
			tableOIDs[i] = int64(field.TableOID)
			attributeNumbers[i] = int64(field.TableAttributeNumber)
		}

		rows, err := pgxConn.Query(ctx, describeColumnsSQL, typeOIDs, tableOIDs, attributeNumbers)
		if err != nil {
			return err
		}
		defer rows.Close()
		for rows.Next() {
			var ordinal int64
			var declaredType, table, originColumn string
			if err := rows.Scan(&ordinal, &declaredType, &table, &originColumn); err != nil {
				return err
			}
			column := &described[ordinal-1]
			column.DeclaredType = declaredType
			column.Table = table
			column.OriginColumn = originColumn
		}
		return rows.Err()
	})
	if err != nil {
		return nil, err
	}
	return described, nil
}

// --- DDL from a snapshot shape (ADR-0043) -------------------------------------------------

// CreateTableFromSchemaSQL renders a table snapshot as CREATE TABLE IF NOT EXISTS: storage types as recorded
// (format_type spellings), one generated key inline as identity, any other key as the trailing constraint.
func (d *Dialect) CreateTableFromSchemaSQL(schema *core.TableSchema) string {
	var b strings.Builder
	b.WriteString("create table if not exists ")
	b.WriteString(d.QuoteIdentifier(schema.Name))
	b.WriteString(" (")
	first := true
	var plainKeys []string
	hasGeneratedKey := false
	for _, column := range schema.Columns {
		if first {
			b.WriteString("\n    ")
		} else {
			b.WriteString(",\n    ")
		}
		first = false
		b.WriteString(d.QuoteIdentifier(column.Name))
		b.WriteByte(' ')
		b.WriteString(column.StorageType)
		if column.Key && column.Generated {
			hasGeneratedKey = true
			b.WriteString(" generated by default as identity primary key")
			continue
		}
		if !column.Nullable {
			b.WriteString(" not null")
		}
		if column.Key {
			plainKeys = append(plainKeys, d.QuoteIdentifier(column.Name))
		}
	}
	if len(plainKeys) > 0 && !hasGeneratedKey {
		b.WriteString(",\n    primary key (" + strings.Join(plainKeys, ", ") + ")")
	}
	b.WriteString("\n)")
	return b.String()
}

// CreateIndexFromSchemaSQL renders one snapshot index's CREATE INDEX IF NOT EXISTS.
func (d *Dialect) CreateIndexFromSchemaSQL(table string, index core.TableIndex) string {
	unique := ""
	if index.Unique {
		unique = "unique "
	}
	columns := make([]string, len(index.Columns))
	for i, part := range index.Columns {
		columns[i] = d.QuoteIdentifier(part.ColumnName)
		if part.Descending {
			columns[i] += " desc"
		}
	}
	return "create " + unique + "index if not exists " + d.QuoteIdentifier(index.Name) + " on " +
		d.QuoteIdentifier(table) + " (" + strings.Join(columns, ", ") + ")"
}

// CreateViewFromBodySQL is `create or replace view` for a view and `create materialized view if not exists`
// for a materialized view (which has no replace).
func (d *Dialect) CreateViewFromBodySQL(view, body string, materialized bool) string {
	if materialized {
		return "create materialized view if not exists " + d.QuoteIdentifier(view) + " as\n" + body
	}
	return "create or replace view " + d.QuoteIdentifier(view) + " as\n" + body
}

// DropViewSQL is `drop [materialized ]view if exists "v"`.
func (d *Dialect) DropViewSQL(view string, materialized bool) string {
	if materialized {
		return "drop materialized view if exists " + d.QuoteIdentifier(view)
	}
	return "drop view if exists " + d.QuoteIdentifier(view)
}

// ViewDefinitionIsVerbatim is false: pg_get_viewdef reformats the parse tree, so the MIG-012 view guard
// round-trips the expected body through a probe view.
func (*Dialect) ViewDefinitionIsVerbatim() bool { return false }
